import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        CGregAndFriends solver = new CGregAndFriends();
        solver.solve(1, in, out);
        out.close();
    }

    static class CGregAndFriends {
        static final long MOD = 1000000007L;
        static final long INF = (long)1e18 + 1;
        long[][] nCr = new long[100][100];

        long compute(long base, int a, int b, int c, int d) {
            base = (base * nCr[a][b]) % MOD;
            base = (base * nCr[c][d]) % MOD;
            return base;
        }

        void solve(int testNum, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int K = in.nextInt();
            int cnt50 = 0, cnt100 = 0;
            for (int i = 0; i < n; i++) {
                if (in.nextInt() == 50) cnt50++;
                else cnt100++;
            }

            for (int i = 0; i < 100; i++) {
                nCr[i][0] = nCr[i][i] = 1;
                for (int j = 1; j < i; j++) {
                    nCr[i][j] = (nCr[i-1][j] + nCr[i-1][j-1]) % MOD;
                }
            }

            long[][][] dist = new long[200][200][2];
            long[][][] count = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                }
            }

            dist[0][0][0] = 0;
            count[0][0][0] = 1;

            Queue<Node> q = new ArrayDeque<>();
            q.add(new Node(0, 0, 0, 0));

            while (!q.isEmpty()) {
                Node node = q.poll();
                int x = node.x;
                int y = node.y;
                int side = node.side;
                long d = dist[x][y][side];

                if (side == 0) {
                    int rem50 = cnt50 - x;
                    int rem100 = cnt100 - y;
                    for (int take50 = 0; take50 <= rem50; take50++) {
                        for (int take100 = 0; take100 <= rem100; take100++) {
                            if (take50 + take100 == 0) continue;
                            if (take50 * 50 + take100 * 100 > K) break;

                            int nx = x + take50;
                            int ny = y + take100;
                            int nside = side ^ 1;
                            long nd = d + 1;

                            if (dist[nx][ny][nside] >= nd) {
                                if (dist[nx][ny][nside] > nd) {
                                    dist[nx][ny][nside] = nd;
                                    q.add(new Node(nx, ny, nside, nd));
                                }
                                count[nx][ny][nside] = (count[nx][ny][nside] + compute(count[x][y][side], rem50, take50, rem100, take100)) % MOD;
                            }
                        }
                    }
                } else {
                    int rem50 = x;
                    int rem100 = y;
                    for (int take50 = 0; take50 <= rem50; take50++) {
                        for (int take100 = 0; take100 <= rem100; take100++) {
                            if (take50 + take100 == 0) continue;
                            if (take50 * 50 + take100 * 100 > K) break;

                            int nx = x - take50;
                            int ny = y - take100;
                            int nside = side ^ 1;
                            long nd = d + 1;

                            if (dist[nx][ny][nside] >= nd) {
                                if (dist[nx][ny][nside] > nd) {
                                    dist[nx][ny][nside] = nd;
                                    q.add(new Node(nx, ny, nside, nd));
                                }
                                count[nx][ny][nside] = (count[nx][ny][nside] + compute(count[x][y][side], rem50, take50, rem100, take100)) % MOD;
                            }
                        }
                    }
                }
            }

            if (dist[cnt50][cnt100][1] == INF) {
                System.out.println(-1);
            } else {
                System.out.println(dist[cnt50][cnt100][1]);
            }
            System.out.println(count[cnt50][cnt100][1]);
        }

        static class Node {
            int x, y, side;
            long d;
            Node(int x, int y, int side, long d) {
                this.x = x;
                this.y = y;
                this.side = side;
                this.d = d;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int p, len;

        InputReader(InputStream in) { this.in = in; }

        private int nextByte() {
            if (len == -1) throw new RuntimeException();
            if (p >= len) {
                p = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[p++];
        }

        public int nextInt() {
            int c = nextByte();
            while (c <= 32) c = nextByte();
            int val = 0, sign = 1;
            if (c == '-') { sign = -1; c = nextByte(); }
            for (; '0' <= c && c <= '9'; c = nextByte()) val = val * 10 + c - '0';
            return val * sign;
        }
    }
}
